/**
 * @summary Get recent signals for a mentor (client app)
 */
export const getAppGetSignalsUrl = (params: AppGetSignalsParams) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {
    if (value !== undefined) {
      normalizedParams.append(key, value === null ? "null" : value.toString());
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0
    ? `/api/app/signals?${stringifiedParams}`
    : `/api/app/signals`;
};

export const appGetSignals = async (
  params: AppGetSignalsParams,
  options?: RequestInit,
): Promise<TradeSignal[]> => {
  return customFetch<TradeSignal[]>(getAppGetSignalsUrl(params), {
    ...options,
    method: "GET",
  });
};

export const getAppGetSignalsQueryKey = (params?: AppGetSignalsParams) => {
  return [`/api/app/signals`, ...(params ? [params] : [])] as const;
};

export const getAppGetSignalsQueryOptions = <
  TData = Awaited<ReturnType<typeof appGetSignals>>,
  TError = ErrorType<unknown>,
>(
  params: AppGetSignalsParams,
  options?: {
    query?: UseQueryOptions<
      Awaited<ReturnType<typeof appGetSignals>>,
      TError,
      TData
    >;
    request?: SecondParameter<typeof customFetch>;
  },
) => {
  const { query: queryOptions, request: requestOptions } = options ?? {};

  const queryKey = queryOptions?.queryKey ?? getAppGetSignalsQueryKey(params);

  const queryFn: QueryFunction<Awaited<ReturnType<typeof appGetSignals>>> = ({
    signal,
  }) => appGetSignals(params, { signal, ...requestOptions });

  return { queryKey, queryFn, ...queryOptions } as UseQueryOptions<
    Awaited<ReturnType<typeof appGetSignals>>,
    TError,
    TData
  > & { queryKey: QueryKey };
};

